    probe.listen(0, host, () => resolvePromise());
  });
  const addr = probe.address();
  await new Promise<void>((resolvePromise) => probe.close(() => resolvePromise()));
  if (!addr || typeof addr === "string") {
    throw new Error("failed to allocate local port");
  }
  return addr.port;
